import base64,lzma,struct,time,sys
import serial
from pathlib import Path

PORT='/dev/cu.usbserial-130'
BAUD=115200
PEN_UP=6.12
PEN_DOWN=2.97
ZF=180
TF=3000
DF=1200

# Decode compact validated geometry payload (uvarint + zigzag deltas, 0.01 mm units).
data=lzma.decompress(base64.b64decode(Path('/tmp/lemur10-geom.b64').read_text().strip()))
pos=0
def get_uvar():
    global pos
    value=0; shift=0
    while True:
        if pos>=len(data): raise RuntimeError('truncated geometry payload')
        b=data[pos]; pos+=1
        value |= (b & 0x7f) << shift
        if not (b & 0x80): return value
        shift += 7
        if shift>35: raise RuntimeError('invalid varint')
def unzz(v): return (v >> 1) ^ -(v & 1)
poly_count=get_uvar()
polys=[]
for _ in range(poly_count):
    n=get_uvar()
    if n < 2: raise RuntimeError('invalid short polyline')
    x=get_uvar(); y=get_uvar(); pts=[(x/100.0,y/100.0)]
    for _ in range(n-1):
        x += unzz(get_uvar()); y += unzz(get_uvar()); pts.append((x/100.0,y/100.0))
    polys.append(pts)
if pos != len(data): raise RuntimeError('trailing geometry payload bytes')
if len(polys) != 283 or sum(map(len,polys)) != 7046:
    raise RuntimeError(f'unexpected geometry shape: {len(polys)} polylines / {sum(map(len,polys))} points')

commands=['G90',f'G0 Z{PEN_UP:.2f} F{ZF}']
for poly in polys:
    x,y=poly[0]
    commands.append(f'G0 X{x:.2f} Y{y:.2f} F{TF}')
    commands.append(f'G0 Z{PEN_DOWN:.2f} F{ZF}')
    for x,y in poly[1:]:
        commands.append(f'G1 X{x:.2f} Y{y:.2f} F{DF}')
    commands.append(f'G0 Z{PEN_UP:.2f} F{ZF}')
commands.append('M400')

# Fail-closed validation immediately before opening the port.
allowed={'G90','G0','G1','M400'}
forbidden={'G28','G91','M104','M109','M140','M190'}
for i,cmd in enumerate(commands,1):
    op=cmd.split()[0]
    if op not in allowed or op in forbidden or ' E' in cmd:
        raise RuntimeError(f'unsafe command {i}: {cmd}')
    if op in {'G0','G1'} and (' X' in cmd or ' Y' in cmd):
        vals={p[0]:float(p[1:]) for p in cmd.split()[1:]}
        if not (8.0 <= vals['X'] <= 218.0 and 41.0 <= vals['Y'] <= 225.0):
            raise RuntimeError(f'XY out of bounds at {i}: {cmd}')
if commands[0] != 'G90' or commands[-1] != 'M400':
    raise RuntimeError('invalid job framing')
print(f'JOB_VALIDATED commands={len(commands)} polylines={len(polys)} points={sum(map(len,polys))}', flush=True)
print(f'JOB_BOUNDS X=63.79..163.00 Y=84.21..181.79 PEN_UP={PEN_UP:.2f} PEN_DOWN={PEN_DOWN:.2f}', flush=True)

def wait_ok(ser, command, timeout):
    deadline=time.monotonic()+timeout
    while time.monotonic()<deadline:
        raw=ser.readline()
        if not raw: continue
        text=raw.decode('utf-8',errors='replace').strip()
        if not text: continue
        low=text.lower()
        if low.startswith('error') or 'printer halted' in low or 'kill() called' in low:
            raise RuntimeError(f'printer error after {command!r}: {text}')
        if low.startswith('resend') or low.startswith('rs '):
            raise RuntimeError(f'unexpected resend request after {command!r}: {text}')
        if low == 'ok' or low.startswith('ok '): return
    raise TimeoutError(f'timeout waiting for ok after {command!r}')

with serial.Serial(PORT,BAUD,timeout=0.25,write_timeout=2) as ser:
    time.sleep(2.0)
    ser.reset_input_buffer()
    total=len(commands)
    for idx,command in enumerate(commands,1):
        ser.write((command+'\n').encode('ascii')); ser.flush()
        wait_ok(ser,command,300.0 if command=='M400' else 30.0)
        if idx == 1 or idx % 250 == 0 or idx == total:
            print(f'PROGRESS {idx}/{total}', flush=True)
print('RESULT:LEMUR_10CM_JOB_COMPLETE_PEN_UP', flush=True)
